import {useCoffeTrace} from '../hooks/use-coffe-trace'
// eslint-disable-next-line @github-ui/github-monorepo/restrict-relay-imports
import {TraceProvider} from '@github-ui/copilot-chat/components/tracing/TraceProvider'
import {useAppPayload} from '@github-ui/react-core/use-app-payload'
// eslint-disable-next-line @github-ui/github-monorepo/restrict-relay-imports
import type {CopilotChatPayload} from '@github-ui/copilot-chat/utils/copilot-chat-types'
// eslint-disable-next-line @github-ui/github-monorepo/restrict-relay-imports
import {TraceDisplay} from '@github-ui/copilot-chat/components/tracing/TraceDisplay'

export function ThreadView() {
  const appPayload = useAppPayload<CopilotChatPayload>()

  return (
    <TraceProvider apiURL={appPayload.apiURL} ssoOrgs={[]}>
      <ThreadViewInner />
    </TraceProvider>
  )
}

function ThreadViewInner() {
  const {query, threadId} = useCoffeTrace()
  if (query.isLoading) {
    return <div>Loading...</div>
  } else if (query.isError) {
    return <div>Error: {query.error.message}</div>
  } else {
    return <TraceDisplay sharedThreadChannel={null} threadId={threadId} />
  }
}

try{ ThreadView.displayName ||= 'ThreadView' } catch {}
try{ ThreadViewInner.displayName ||= 'ThreadViewInner' } catch {}